package com.termux.app.terminow;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import org.junit.Test;

import java.io.ByteArrayInputStream;
import java.security.cert.CertificateException;
import java.security.cert.CertificateFactory;
import java.security.cert.X509Certificate;
import java.util.Base64;

import javax.net.ssl.X509TrustManager;

/**
 * Unit tests for the pure Proxmox helpers, with a fixture self-signed certificate (generated by
 * openssl). These do not touch the network; {@link TerminowProxmox#testConnection} needs a real server.
 */
public class TerminowProxmoxTest {

    // A self-signed cert (CN=pve.test) and its openssl SHA-256 fingerprint.
    private static final String CERT_DER_B64 =
        "MIIDBzCCAe+gAwIBAgIUCv09iaShBhjQP5tT9TDcY0R6F50wDQYJKoZIhvcNAQELBQAwEzERMA8GA1UEAwwIcHZlLnRlc3Qw"
        + "HhcNMjYxMDI4MDQxNDQ2WhcNMzYxMDI1MDQxNDQ2WjATMREwDwYDVQQDDAhwdmUudGVzdDCCASIwDQYJKoZIhvcNAQEBBQAD"
        + "ggEPADCCAQoCggEBAIeEmAWrUMPe1PYvv//Hkeq1nVZC1O7QNwfUVVDp9vvGFjZOELH0DpxHJaIMhvImp98ggWbJKGyGLXef"
        + "4QBvtQa9LL9XafKZBKaGHZu6wFg2PPzlfsP/bh9tBhpK6w1srGDKviCyr3lAOLW/fKb1BHxHBJAzJjLvlMwZNY0VfoA9fld9"
        + "QT4PKYPUnXOJAmG0B+DO+3skbdtF0u8lvBqnBf9N/rPPNySkOc+v3uvpVuIccfOmdC3/RUJ5dTfRNAaPVyQI9dw+DstYdn8x"
        + "FiSa02Gk78f7xkEHKKR9VNHBsA6IlrxqcaTAGGkVOlVXm4NXjCblTA5grC8rLYatbPREF1ECAwEAAaNTMFEwHQYDVR0OBBYE"
        + "FD63/sL4CW+o1CmxBNoBZIodAazJMB8GA1UdIwQYMBaAFD63/sL4CW+o1CmxBNoBZIodAazJMA8GA1UdEwEB/wQFMAMBAf8w"
        + "DQYJKoZIhvcNAQELBQADggEBAGSTbHQRFjF3gwMabV2l72dGQxlpm9aTtufa7KNb2SYOlCvkjUBA5hSK9/wDugNZh4sLwPJq"
        + "SY0umez0ztae5piys8bBjf/qfV+dZNzr4n6BkmCxPbjZCFq1CuLDPUbL3vTCWgDVLs8rvx/ExXJ60mISxc2Wr7N2ZQG3ALSR"
        + "D8oGhu/JHO3X+MPQlaFloyxSCI9xKBcrq4j8VKMlNfdAnPSl8S0hxck27e0VdRIf+t33C7dvyIgfZ5Su2B0Hk/qrxhLEefRg"
        + "qAY75YAy9WXjW4XPbWKp+s2jsa4e72DjhhcVhbZX3BVO6OE8FQ263PC7wabXJyvbr9EHaOHljhwKke0=";
    private static final String CERT_FINGERPRINT =
        "C2:2B:A8:1F:57:09:47:5F:16:9E:BC:04:E2:AD:C0:2C:7D:84:D4:AB:82:28:B4:D5:23:EA:65:05:7F:E7:AF:88";

    private static X509Certificate fixtureCert() throws CertificateException {
        byte[] der = Base64.getDecoder().decode(CERT_DER_B64);
        return (X509Certificate) CertificateFactory.getInstance("X.509")
            .generateCertificate(new ByteArrayInputStream(der));
    }

    @Test
    public void authHeaderIsTheProxmoxTokenForm() {
        assertEquals("PVEAPIToken=root@pam!mon=abc-123",
            TerminowProxmox.authHeader("root@pam!mon", "abc-123"));
    }

    @Test
    public void baseUrlDefaultsPortAndBracketsIpv6() {
        assertEquals("https://10.0.0.5:8006/api2/json", TerminowProxmox.baseUrl("10.0.0.5", 8006));
        assertEquals("https://pve.local:9000/api2/json", TerminowProxmox.baseUrl("pve.local", 9000));
        assertEquals("https://pve.local:8006/api2/json", TerminowProxmox.baseUrl("pve.local", 0));
        assertEquals("https://[fe80::1]:8006/api2/json", TerminowProxmox.baseUrl("fe80::1", 8006));
    }

    @Test
    public void fingerprintMatchesOpenssl() throws Exception {
        assertEquals(CERT_FINGERPRINT, TerminowProxmox.fingerprintOf(fixtureCert()));
    }

    @Test
    public void pinnedTrustManagerAcceptsMatchingRejectsOther() throws Exception {
        X509Certificate[] chain = {fixtureCert()};
        // matching fingerprint (case-insensitive) is accepted
        TerminowProxmox.pinnedTrustManager(CERT_FINGERPRINT.toLowerCase()).checkServerTrusted(chain, "RSA");
        // a different fingerprint is rejected
        try {
            TerminowProxmox.pinnedTrustManager("00:11:22").checkServerTrusted(chain, "RSA");
            fail("expected a CertificateException for a mismatched fingerprint");
        } catch (CertificateException expected) {
            assertTrue(expected.getMessage().toLowerCase().contains("fingerprint"));
        }
    }

    @Test
    public void pinnedTrustManagerRejectsEmptyChain() {
        X509TrustManager tm = TerminowProxmox.pinnedTrustManager(CERT_FINGERPRINT);
        try {
            tm.checkServerTrusted(new X509Certificate[0], "RSA");
            fail("expected a CertificateException for an empty chain");
        } catch (CertificateException expected) {
            // ok
        }
    }

    @Test
    public void parseNodesReadsNamesAndStatus() {
        java.util.List<TerminowProxmox.PveNode> nodes = TerminowProxmox.parseNodes(
            "{\"data\":[{\"node\":\"pve\",\"status\":\"online\"},{\"node\":\"pve2\",\"status\":\"offline\"}]}");
        assertEquals(2, nodes.size());
        assertEquals("pve", nodes.get(0).name);
        assertEquals("online", nodes.get(0).status);
        assertEquals("offline", nodes.get(1).status);
        assertTrue(TerminowProxmox.parseNodes("{}").isEmpty());
        assertTrue(TerminowProxmox.parseNodes("bad").isEmpty());
    }

    @Test
    public void parseGuestsReadsVmidNameStatusAndType() {
        java.util.List<TerminowProxmox.PveGuest> g = TerminowProxmox.parseGuests(
            "{\"data\":[{\"vmid\":100,\"name\":\"web\",\"status\":\"running\"},{\"vmid\":101,\"status\":\"stopped\"}]}",
            "qemu", "pve");
        assertEquals(2, g.size());
        assertEquals(100, g.get(0).vmid);
        assertEquals("web", g.get(0).name);
        assertEquals("running", g.get(0).status);
        assertEquals("qemu", g.get(0).type);
        assertEquals("pve", g.get(0).node);
        assertEquals("vm-101", g.get(1).name);   // name falls back to vm-<vmid>
    }

    @Test
    public void guestActionAndTaskPaths() {
        TerminowProxmox.PveGuest vm = new TerminowProxmox.PveGuest();
        vm.vmid = 100; vm.type = "qemu"; vm.node = "pve";
        assertEquals("/nodes/pve/qemu/100/status/start", TerminowProxmox.guestActionPath(vm, "start"));
        assertEquals("/nodes/pve/qemu/100/status/shutdown", TerminowProxmox.guestActionPath(vm, "shutdown"));
        TerminowProxmox.PveGuest ct = new TerminowProxmox.PveGuest();
        ct.vmid = 201; ct.type = "lxc"; ct.node = "pve2";
        assertEquals("/nodes/pve2/lxc/201/status/reboot", TerminowProxmox.guestActionPath(ct, "reboot"));
        assertEquals("/nodes/pve/tasks/UPID:x/status", TerminowProxmox.taskStatusPath("pve", "UPID:x"));
    }

    @Test
    public void parseUpidAndTaskStatus() {
        assertEquals("UPID:pve:00:...:qmstart:100:root@pam:",
            TerminowProxmox.parseUpid("{\"data\":\"UPID:pve:00:...:qmstart:100:root@pam:\"}"));
        assertEquals("", TerminowProxmox.parseUpid("{}"));
        TerminowProxmox.TaskStatus running = TerminowProxmox.parseTaskStatus("{\"data\":{\"status\":\"running\"}}");
        assertTrue(running.running);
        TerminowProxmox.TaskStatus done = TerminowProxmox.parseTaskStatus("{\"data\":{\"status\":\"stopped\",\"exitstatus\":\"OK\"}}");
        assertTrue(!done.running);
        assertEquals("OK", done.exitStatus);
    }

    @Test
    public void webUrlFromConnection() {
        TerminowProxmox.Connection c = new TerminowProxmox.Connection();
        c.host = "pve.local"; c.port = 8006;
        assertEquals("https://pve.local:8006/", TerminowProxmox.webUrl(c));
        c.host = "fe80::1"; c.port = 0;
        assertEquals("https://[fe80::1]:8006/", TerminowProxmox.webUrl(c));
    }

    @Test
    public void parseVersionReadsTheData() {
        assertEquals("8.1.4", TerminowProxmox.parseVersion("{\"data\":{\"version\":\"8.1.4\",\"release\":\"8.1\"}}"));
        assertEquals("", TerminowProxmox.parseVersion("{\"data\":{}}"));
        assertEquals("", TerminowProxmox.parseVersion("not json"));
        assertEquals("", TerminowProxmox.parseVersion("{}"));
    }
}
